chartjs.data:
model -> {
	days = now().roundDay()
		.recursion(d -> $d.toSystemCalendar().withDayAdded(-1).toDate().roundDay(), 0, 30)
		.reverse();
	byDay = all(`tl.ai.execution:AgentExecution`)
		.filter(e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`) >= $days.firstElement())
		.groupBy(e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`).roundDay());
	counts = status -> $days.map(d -> {
		runs = $byDay[$d];
		ifElse(isEmpty($runs), 0,
			$runs.filter(e -> $e.get(`tl.ai.execution:AgentExecution#status`) == $status).size());
	});
	bar = status -> color -> {
		'label': $status.label(),
		'data': $counts($status),
		'backgroundColor': $color
	};
	{
		'type': 'bar',
		'data': {
			'labels': $days.map(d -> dateFormat('dd.MM.').format($d)),
			'datasets': list(
				$bar(`tl.ai.execution:ExecutionStatus#COMPLETE`)('#04a38d'),
				$bar(`tl.ai.execution:ExecutionStatus#ERROR`)('#d3181b'),
				$bar(`tl.ai.execution:ExecutionStatus#REJECTED`)('#d3a118'),
				$bar(`tl.ai.execution:ExecutionStatus#CANCELLED`)('#8a8a8a'),
				$bar(`tl.ai.execution:ExecutionStatus#RUNNING`)('#2968c8')
			)
		},
		'options': {
			'maintainAspectRatio': false,
			'plugins': { 'legend': { 'position': 'bottom' } },
			'scales': {
				'x': { 'stacked': true },
				'y': { 'stacked': true, 'beginAtZero': true }
			}
		}
	};
}
